B=[
('الْمَدِينَةُ','Medine',[
('فِي خِلَافَةِ عُثْمَانَ بْنِ عَفَّانَ اتَّسَعَتْ دَوْلَةُ الْإِسْلَامِ، وَكَثُرَتِ الْأَمْوَالُ.','Osman b. Affân’ın hilafetinde İslâm devleti genişledi ve mallar çoğaldı.'),
('وَكَانَ فِي الْمَدِينَةِ فَتَاةٌ يَتِيمَةٌ مِنْ قُرَيْشٍ، تُرَبِّيهَا أُمُّ الْمُؤْمِنِينَ عَائِشَةُ.','Medine’de, mü’minlerin annesi Âişe’nin büyüttüğü Kureyşli yetim bir kız vardı.'),
('وَكَانَتْ عَفِيفَةً كَرِيمَةً، فَسَمَّاهَا النَّاسُ: عَذْرَاءَ قُرَيْشٍ.','İffetli ve soyluydu; insanlar ona “Kureyş Bakiresi” adını verdiler.'),
('وَكَانَ يُحِبُّهَا شَابٌّ صَالِحٌ اسْمُهُ مُحَمَّدُ بْنُ أَبِي بَكْرٍ.','Muhammed b. Ebû Bekir adında salih bir genç onu seviyordu.'),
('وَلَكِنَّ الْأَيَّامَ كَانَتْ تَحْمِلُ فِتْنَةً عَظِيمَةً.','Ama günler büyük bir fitne taşıyordu.')]),
('الْفِتْنَةُ','Fitne',[
('فَقَدْ جَاءَتْ جَمَاعَاتٌ مِنْ مِصْرَ وَالْعِرَاقِ تَشْكُو مِنْ بَعْضِ الْوُلَاةِ.','Mısır’dan ve Irak’tan bazı valilerden şikâyet eden topluluklar geldi.'),
('وَحَاصَرُوا بَيْتَ عُثْمَانَ أَيَّامًا، وَمَنَعُوا عَنْهُ الْمَاءَ.','Osman’ın evini günlerce kuşattılar ve ona suyu kestiler.'),
('وَكَانَ عُثْمَانُ شَيْخًا كَبِيرًا، فَرَفَضَ أَنْ يُقَاتِلَ الْمُسْلِمُونَ دُونَهُ، وَقَالَ: «لَا أُرِيدُ أَنْ يُرَاقَ بِسَبَبِي دَمٌ.»','Osman çok yaşlıydı; Müslümanların onu savunmak için savaşmasını reddetti ve dedi ki: “Benim yüzümden kan dökülmesini istemem.”'),
('ثُمَّ دَخَلَ عَلَيْهِ بَعْضُهُمْ وَهُوَ يَقْرَأُ الْقُرْآنَ، فَقَتَلُوهُ.','Sonra bazıları o Kur’an okurken yanına girdi ve onu öldürdüler.'),
('فَبَكَتِ الْمَدِينَةُ، وَانْقَسَمَ النَّاسُ.','Medine ağladı ve insanlar bölündü.')]),
('عَلِيٌّ','Ali',[
('فَبَايَعَ النَّاسُ عَلِيَّ بْنَ أَبِي طَالِبٍ خَلِيفَةً.','İnsanlar Ali b. Ebû Tâlib’e halife olarak biat ettiler.'),
('وَطَلَبَ بَعْضُ الصَّحَابَةِ أَنْ يُقْتَصَّ مِنْ قَتَلَةِ عُثْمَانَ أَوَّلًا.','Bazı sahabiler önce Osman’ın katillerinden kısas alınmasını istediler.'),
('وَرَأَى عَلِيٌّ أَنْ تَهْدَأَ الْأُمُورُ قَبْلَ ذَلِكَ.','Ali ise bundan önce işlerin yatışması gerektiğini düşündü.'),
('فَخَرَجَتْ عَائِشَةُ وَطَلْحَةُ وَالزُّبَيْرُ إِلَى الْبَصْرَةِ.','Âişe, Talha ve Zübeyr Basra’ya çıktılar.'),
('وَكَانَ كُلُّ فَرِيقٍ يُرِيدُ الْخَيْرَ لِلْأُمَّةِ، وَلَكِنَّ الْأَهْوَاءَ وَالْمُفْسِدِينَ أَشْعَلُوا النَّارَ.','Her taraf ümmet için iyilik istiyordu ama hevalar ve fitneciler ateşi yaktılar.')]),
('الْجَمَلُ','Cemel',[
('فَالْتَقَى الْفَرِيقَانِ عِنْدَ الْبَصْرَةِ، وَكَانَتْ عَائِشَةُ عَلَى جَمَلٍ، فَسُمِّيَتِ الْمَعْرَكَةُ: مَوْقِعَةَ الْجَمَلِ.','İki taraf Basra yakınında karşılaştı; Âişe bir devenin üzerindeydi, savaşa bu yüzden Cemel Vak‘ası dendi.'),
('وَحَاوَلَ الْعُقَلَاءُ الصُّلْحَ، وَكَادَ يَتِمُّ، وَلَكِنَّ الْفِتْنَةَ بَدَأَتْ فِي اللَّيْلِ.','Akıllılar barışa çalıştı ve neredeyse olacaktı ama fitne gece başladı.'),
('فَقُتِلَ خَلْقٌ كَثِيرٌ، وَحَزِنَ عَلِيٌّ حُزْنًا شَدِيدًا.','Çok insan öldü ve Ali derinden üzüldü.'),
('ثُمَّ أَكْرَمَ عَلِيٌّ عَائِشَةَ، وَأَرْسَلَهَا إِلَى الْمَدِينَةِ مَعَ أَخِيهَا مُحَمَّدٍ.','Sonra Ali Âişe’ye saygı gösterdi ve onu kardeşi Muhammed ile Medine’ye gönderdi.'),
('وَفِي رِوَايَةِ زَيْدَانَ تَبْقَى عَذْرَاءُ قُرَيْشٍ وَفِيَّةً، تَنْتَظِرُ أَنْ تَنْطَفِئَ الْفِتْنَةُ.','Zeydân’ın romanında Kureyş Bakiresi vefalı kalır ve fitnenin sönmesini bekler.'),
('وَيَقُولُ: الْفِتْنَةُ إِذَا أَقْبَلَتْ لَمْ يَعْرِفْهَا إِلَّا الْعُلَمَاءُ، وَإِذَا أَدْبَرَتْ عَرَفَهَا كُلُّ أَحَدٍ.','Ve der ki: Fitne gelirken onu yalnız âlimler tanır; giderken herkes tanır.')]),
]
